begin;

-- Private storage for HMAC-SHA256 keys generated by the authenticated Guardian
-- Edge Function. The browser roles never receive table privileges.
create table public.auth_rate_limits (
  key_hash text not null check (key_hash ~ '^[0-9a-f]{64}$'),
  action text not null check (action in ('ai_guardian_user', 'ai_guardian_ip')),
  window_started_at timestamptz not null,
  attempt_count integer not null check (attempt_count > 0),
  primary key (key_hash, action)
);

alter table public.auth_rate_limits enable row level security;
revoke all on table public.auth_rate_limits from public, anon, authenticated, service_role;

create or replace function public.consume_auth_rate_limit(
  p_key_hash text,
  p_action text,
  p_attempt_limit integer,
  p_window_seconds integer
)
returns boolean
language plpgsql
security definer
set search_path = pg_catalog, public, pg_temp
as $$
declare
  request_time timestamptz := clock_timestamp();
  updated_count integer;
begin
  -- This RPC is a server-side primitive. The Edge Function authenticates the
  -- patient first, derives a peppered hash, and calls through service_role.
  if auth.role() is distinct from 'service_role' then
    raise insufficient_privilege using message = 'Service role required';
  end if;

  if p_key_hash is null or p_key_hash !~ '^[0-9a-f]{64}$'
    or p_action not in ('ai_guardian_user', 'ai_guardian_ip')
    or p_attempt_limit not between 1 and 1000
    or p_window_seconds not between 1 and 86400 then
    raise invalid_parameter_value using message = 'Invalid rate limit parameters';
  end if;

  -- The unique-key upsert serializes concurrent requests for this key. The
  -- first attempt in a fixed window is count 1; all later attempts, including
  -- rejected attempts, increment that same window.
  insert into public.auth_rate_limits as current_limit
    (key_hash, action, window_started_at, attempt_count)
  values (p_key_hash, p_action, request_time, 1)
  on conflict (key_hash, action) do update
    set window_started_at = case
          when current_limit.window_started_at <= request_time - make_interval(secs => p_window_seconds)
            then request_time
          else current_limit.window_started_at
        end,
        attempt_count = case
          when current_limit.window_started_at <= request_time - make_interval(secs => p_window_seconds)
            then 1
          else current_limit.attempt_count + 1
        end
  returning attempt_count into updated_count;

  return updated_count <= p_attempt_limit;
end;
$$;

revoke all on function public.consume_auth_rate_limit(text, text, integer, integer)
  from public, anon, authenticated;
grant execute on function public.consume_auth_rate_limit(text, text, integer, integer)
  to service_role;

commit;
